\textbf{Method} & \textbf{3-class F1} & \textbf{Binary F1} \\
\midrule
7-feature ensemble    & 0.762 & \textbf{0.694} \\
4-det.\ + surface     & 0.771 & 0.690 \\
4-detector ens.\      & 0.769 & 0.684 \\
Avg-LogProb           & 0.685 & 0.642 \\
